<script setup>
import {onMounted,ref,watch,nextTick} from 'vue'
import {Plus,Trash2,Play,MessageSquare,AudioLines} from 'lucide-vue-next'
import VoiceComposer from '../components/VoiceComposer.vue'
import {state,refreshThreads,newThread,openThread,deleteThread,replay,notice} from '../state'
import {data} from '../transport'
const deleting=ref(''),scroll=ref(null),dialog=ref(null)
watch(deleting,async value=>{await nextTick();if(value&&!dialog.value.open)dialog.value.showModal();else if(!value&&dialog.value.open)dialog.value.close()})
onMounted(async()=>{try{await refreshThreads();if(state.tid)await openThread(state.tid)}catch(e){notice(e.message)}})
watch(()=>state.messages.map(m=>m.text).join('\n'),async()=>{await nextTick();if(scroll.value)scroll.value.scrollTop=scroll.value.scrollHeight})
async function remove(){try{await deleteThread(deleting.value);deleting.value=''}catch(e){notice(e.message)}}
</script>
<template><div class="assistant-surface"><div class="compact-intro"><div><div class="eyebrow">VOICE CONTROL</div><h1>Voice assistant</h1></div><button class="button primary" @click="newThread"><Plus :size="16"/> New conversation</button></div><div class="chat-layout"><div class="chat-main"><div class="chat-head"><span class="assistant-symbol">✳</span><div><strong>LCC</strong><small>Test questions and commands for your workstation</small></div><span class="tag">{{state.voice==='lessac'?'Lessac':'Custom voice'}}</span></div><div ref="scroll" class="chat-messages"><div v-if="!state.messages.length" class="chat-empty"><AudioLines :size="39"/><h2>Enter a question or command</h2><p>“Open the valve test.”<br>“When is a valve considered leaky?”</p></div><div v-for="m in state.messages" :key="m.id" class="message" :class="m.kind"><small>{{m.kind==='user'?'You':'LCC'}}</small><div class="bubble">{{m.text||'Preparing response …'}}<button v-if="data(m).audio_id" class="audio-replay" @click="replay(m)" title="Play response"><Play :size="14"/> Listen to response</button></div></div><div v-if="state.sending" class="thinking">Preparing response …</div></div><VoiceComposer/></div><aside class="thread-panel"><div class="thread-title"><span>CONVERSATIONS</span><span>{{state.threads.length}}</span></div><div v-if="!state.threads.length" class="muted small">No conversations yet.</div><div v-for="t in state.threads" :key="t.id" class="thread" :class="{active:state.tid===t.id}"><button class="thread-open" @click="openThread(t.id)"><MessageSquare :size="15"/><span>{{t.title}}<small>{{t.created}}</small></span></button><button class="icon-button danger" @click="deleting=t.id" title="Delete conversation"><Trash2 :size="15"/></button></div></aside></div><Teleport to="body"><dialog ref="dialog" class="app-dialog" @cancel="deleting=''" @click.self="deleting=''"><div role="dialog" aria-modal="true" aria-labelledby="delete-title" class="modal"><span class="modal-icon danger"><Trash2 :size="24"/></span><h2 id="delete-title">Delete conversation?</h2><p>All messages in this conversation will be deleted. Inspection reports and saved audio will be retained.</p><div class="modal-actions"><button class="button outline" autofocus @click="deleting=''">Keep</button><button class="button danger" @click="remove">Delete conversation</button></div></div></dialog></Teleport></div></template>
